using Alterverse.Characters;using Alterverse.Combat;using UnityEngine;
namespace Alterverse.Visuals
{
public sealed class HeroVisualMotion:MonoBehaviour
{
private HeroIdentity identity;private Health health;private Transform visualRoot;private Vector3 basePos,lastPos;private float seed;private void Start(){identity=GetComponent<HeroIdentity>();health=GetComponent<Health>();seed=Mathf.Abs(GetInstanceID()%97)*.13f;visualRoot=transform.Find("DF_VisualRoot");if(visualRoot!=null)basePos=visualRoot.localPosition;lastPos=transform.position;}
private void LateUpdate(){if(visualRoot==null||health==null)return;float t=Time.time+seed;float speed=(transform.position-lastPos).magnitude/Mathf.Max(Time.deltaTime,.001f);lastPos=transform.position;if(health.IsDead){visualRoot.localPosition=Vector3.Lerp(visualRoot.localPosition,basePos+Vector3.down*.5f,1-Mathf.Exp(-8*Time.deltaTime));visualRoot.localRotation=Quaternion.Slerp(visualRoot.localRotation,Quaternion.Euler(0,0,72),1-Mathf.Exp(-6*Time.deltaTime));return;}HeroId hero=identity!=null?identity.Hero:HeroId.Veyr;float weight=(hero==HeroId.Kaelon||hero==HeroId.Rook)?.7f:1f;float cadence=speed>.25f?7.5f:2.8f;float bob=Mathf.Sin(t*cadence)*(.025f+.018f*Mathf.Clamp01(speed/5))*weight;float lean=Mathf.Sin(t*(speed>.25f?cadence*.5f:1.7f))*(hero==HeroId.Rook?1f:1.7f);if(hero==HeroId.Elyra)bob+=.045f*Mathf.Sin(t*1.35f);if(hero==HeroId.Mira)bob+=.02f*Mathf.Sin(t*1.8f);visualRoot.localPosition=Vector3.Lerp(visualRoot.localPosition,basePos+Vector3.up*bob,1-Mathf.Exp(-12*Time.deltaTime));visualRoot.localRotation=Quaternion.Slerp(visualRoot.localRotation,Quaternion.Euler(speed>.25f?2.5f:0,0,lean),1-Mathf.Exp(-10*Time.deltaTime));AnimateSignature(hero,t,speed);}
private void AnimateSignature(HeroId hero,float t,float speed){Transform orbitL=visualRoot.Find("DF_OrbitL"),orbitR=visualRoot.Find("DF_OrbitR");if(orbitL!=null)orbitL.localPosition=new Vector3(Mathf.Cos(t*1.4f)*.72f,.48f+Mathf.Sin(t*1.4f)*.12f,Mathf.Sin(t*1.4f)*.28f);if(orbitR!=null)orbitR.localPosition=new Vector3(Mathf.Cos(t*1.4f+Mathf.PI)*.68f,.3f+Mathf.Sin(t*1.4f+Mathf.PI)*.12f,Mathf.Sin(t*1.4f+Mathf.PI)*.25f);if(hero==HeroId.Mira){Transform l=visualRoot.Find("DF_WingL"),r=visualRoot.Find("DF_WingR");float flap=Mathf.Sin(t*2.1f)*5;if(l!=null)l.localRotation=Quaternion.Euler(0,-18,-18-flap);if(r!=null)r.localRotation=Quaternion.Euler(0,18,18+flap);}if(hero==HeroId.Nyra){Transform cape=visualRoot.Find("DF_Cape");if(cape!=null)cape.localRotation=Quaternion.Euler(8+Mathf.Clamp(speed,0,6)*1.6f,0,8+Mathf.Sin(t*2)*2);}if(hero==HeroId.Veyr&&speed>.25f){Transform a=visualRoot.Find("DF_BladeR");if(a!=null)a.localRotation=Quaternion.Euler(25+Mathf.Sin(t*7)*5,0,-16);}}
}
}
